INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '棒グラフ問題', '2月と4月の新規顧客獲得数の差はいくらか。最も近いものを選びなさい。', NULL, '["30人","40人","50人","60人","70人"]', 2, '["2月は245人、4月は295人である。差は295－245＝50（人）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', '', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '棒グラフ問題', '在庫数が最も多い支店と最も少ない支店の差はいくつか。最も近いものを選びなさい。', NULL, '["100個","115個","130個","145個","160個"]', 2, '["在庫数が最も多いのはC支店の210個、最も少ないのはE支店の80個である。差は210－80＝130（個）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', '', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '棒グラフ問題', '4カテゴリーの合計売上高に対する、最も売上高が大きいカテゴリーの割合はおよそ何%か。最も近いものを選びなさい。', NULL, '["28.9%","32.2%","35.6%","38.9%","42.2%"]', 2, '["4カテゴリーの合計は320＋180＋275＋125＝900（百万円）。最も売上高が大きいのは食品の320（百万円）である。割合は320÷900＝約0.356となり、百分率に直すと約35.6％となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', '', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '棒グラフ問題', '20代と30代の回答者数を合わせると、全回答者数のおよそ何%を占めるか。最も近いものを選びなさい。', NULL, '["51.5%","54.5%","57.4%","60.4%","63.4%"]', 2, '["全回答者数は45＋120＋150＋95＋60＝470（人）。20代と30代を合わせると120＋150＝270（人）である。割合は270÷470＝約0.574となり、百分率に直すと約57.4％となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', '', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '棒グラフ問題', '5部門の残業時間の平均を上回っている部門はいくつあるか。', NULL, '["なし","1つ","2つ","3つ","4つ"]', 2, '["5部門の残業時間の合計は42＋58＋15＋28＋35＝178（時間）。平均は178÷5＝35.6（時間）となる。この平均を上回っているのは営業（42時間）と開発（58時間）の2部門である。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', '', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '折れ線グラフ問題', '前月と比べた増加率が最も大きいのはどの月か。', NULL, '["2月","3月","4月","5月","6月"]', 3, '["各月の前月比増加率を計算すると、2月は約4.2％、3月は約10.4％、4月は約－4.3％（減少）、5月は約17.4％、6月は約3.2％となる。最も増加率が大きいのは5月である。よって選択肢Dが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', '', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '折れ線グラフ問題', 'A社とB社の売上高の差が最も大きいのはどの月か。', NULL, '["2月","3月","4月","5月","6月"]', 4, '["各月の差（A社－B社）を計算すると、1月20、2月25、3月35、4月－15、5月40、6月55（いずれも百万円）となる。差の絶対値が最も大きいのは6月の55百万円である。よって選択肢Eが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', '', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '折れ線グラフ問題', '2024年の技術者数は、2020年と比較して約何%増加したか。最も近いものを選びなさい。', NULL, '["38.8%","44.7%","50.6%","56.5%","62.4%"]', 2, '["2020年は850人、2024年は1,280人である。増加率は（1,280－850）÷850＝430÷850＝約0.506となり、百分率に直すと約50.6％となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', '', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '折れ線グラフ問題', '前月からの増加量が最も大きいのはどの月か。', NULL, '["3月","4月","5月","6月","増加した月はない"]', 3, '["各月の前月からの変化量を計算すると、2月－30、3月＋20、4月＋40、5月＋30、6月＋50（いずれもkWh）となる。増加量が最も大きいのは6月の50kWhである。よって選択肢Dが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', '', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '折れ線グラフ問題', '売上高に利益率を掛けた利益額が最も大きいのはどの四半期か。', NULL, '["Q1","Q2","Q3","Q4","すべて同じ"]', 3, '["各四半期の利益額（売上高×利益率）を計算すると、Q1は500×0.080＝40.0、Q2は620×0.075＝46.5、Q3は580×0.090＝52.2、Q4は650×0.085＝55.25（いずれも百万円）となる。最も大きいのはQ4である。よって選択肢Dが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', '', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '円グラフ問題', '食費と交通費を合わせた金額はいくらか。最も近いものを選びなさい。', NULL, '["87,500円","94,500円","105,000円","112,000円","122,500円"]', 2, '["食費20％と交通費10％を合わせると30％となる。月収35万円に対して、350,000×0.30＝105,000（円）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', '', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '円グラフ問題', '30代の顧客数は、40代の顧客数より何人多いか。最も近いものを選びなさい。', NULL, '["150人","180人","210人","240人","270人"]', 2, '["顧客総数は4,200人である。30代は4,200×0.30＝1,260人、40代は4,200×0.25＝1,050人となる。差は1,260－1,050＝210（人）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', '', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '円グラフ問題', '人件費は広告費のおよそ何倍か。最も近いものを選びなさい。', NULL, '["1.5倍","2.0倍","2.3倍","2.7倍","3.1倍"]', 3, '["人件費は40％、広告費は15％である。倍率は40÷15＝約2.67となる。よって選択肢Dが正解。金額（人件費3,200万円、広告費1,200万円）で計算しても同じ結果が得られる。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', '', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '円グラフ問題', '天然ガスの割合を円グラフの中心角で表すと、およそ何度になるか。', NULL, '["54度","60度","66度","72度","78度"]', 3, '["円グラフの中心角は全体360度に占める割合に比例する。天然ガスは20％であるため、360×0.20＝72（度）となる。よって選択肢Dが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', '', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '円グラフ問題', 'プロジェクト全体の予算をXとおくとき、広告費と研究開発費を合わせた金額を表す式として正しいものを選びなさい。', NULL, '["X/2","9X/20","11X/20","3X/5","3X/4"]', 2, '["広告費35％と研究開発費20％を合わせると55％となる。全体をXとすると、55／100＝11／20であるから、求める式は11X/20となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', '', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '帯グラフ問題', '「よく利用する」または「たまに利用する」と回答した人の合計割合を比較したとき、米国は日本より何ポイント高いか。', NULL, '["8pt","10pt","12pt","14pt","16pt"]', 2, '["日本の合計は25＋35＝60（％）。米国の合計は42＋30＝72（％）。差は72－60＝12（ポイント）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', '', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '帯グラフ問題', '2020年の全体の発電電力量をMとおくとき、再生可能エネルギーとその他を合わせた発電電力量を表す式として正しいものを選びなさい。', NULL, '["3M/10","7M/20","37M/100","2M/5","9M/20"]', 2, '["2020年の再生可能エネルギーは30％、その他は7％であり、合計は30＋7＝37（％）である。全体をMとすると、求める式は37M/100となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', '', 9100);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '帯グラフ問題', '2000年の水力による発電電力量をHとおくとき、2000年における全体の発電電力量を表す式として正しいものを選びなさい。', NULL, '["6H","25H/3","9H","10H","12H"]', 1, '["2000年の水力の割合は12％である。全体をWとすると、W：H＝100：12という比の関係が成り立つ。これを解くと12W＝100Hとなり、W＝100H/12＝25H/3と導かれる。よって選択肢Bが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', '', 9100);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '帯グラフ問題', '「75%以上取得（100%取得を含む）」の割合は、2023年度から2024年度にかけて何ポイント増加したか。', NULL, '["6pt","8pt","10pt","12pt","14pt"]', 2, '["2023年度の「100%取得」と「75%以上取得」の合計は15＋30＝45（％）。2024年度は22＋33＝55（％）である。差は55－45＝10（ポイント）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', '', NULL);
INSERT INTO questions (category, sub_category, title, question_text, tables_json, options, correct_answer, explanation, difficulty, status, originality_note, image_data_uri, passage_group_id) VALUES ('gab_quantitative', '資料の読み取り', '帯グラフ問題', '20代と60代において、「非常に重視する」または「やや重視する」と回答した割合の合計を比較したとき、その差は何ポイントか。', NULL, '["18pt","21pt","24pt","27pt","30pt"]', 2, '["20代の合計は38＋34＝72（％）。60代の合計は18＋30＝48（％）。差は72－48＝24（ポイント）となる。よって選択肢Cが正解。"]', 4, 'published', 'ユーザー提供のオリジナル問題（GAB: 計数理解/資料の読み取り、グラフ読み取り）', '', NULL);
